def _get_bts_id_arg_name(passed_args):
    if 'gnb_id' in passed_args:
        return 'gnb_id'
    elif 'enb_id' in passed_args:
        return 'enb_id'
    elif 'bts_id' in passed_args:
        return 'bts_id'
    else:
        raise ValueError("One of parameter [gnb_id, enb_id, bts_id] is required")


def login_logout(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])
        passed_args['du_id'] = int(passed_args['du_id'])

        bts_id = passed_args[bts_id_arg_name]
        du_id = passed_args['du_id']

        interface = passed_args.get('interface', 'mplane')
        force = passed_args.get('force_reconnect', False)

        if 'connection' in passed_args and passed_args['connection'] is not None:
            logging.debug("Connection provided. Skipping connect step.")
        else:
            self.connect(bts_id=bts_id, du_id=du_id, interface=interface, force=force)
        result = web_fun(**passed_args)
        return result

    return wrapper


def login_logout_GUI(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        reconnect = False
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])
        passed_args['du_id'] = int(passed_args['du_id'])
        bts_id = passed_args[bts_id_arg_name]
        du_id = passed_args['du_id']
        gui_alias = self.gui_alias.format(bts_id, du_id)

        if gui_alias not in selenium_browser_instances:
            self.login_gui(bts_id=bts_id, du_id=du_id)
        else:
            logging.debug("[{}] Already logged".format(gui_alias))
            self.gui_coam = selenium_browser_instances[gui_alias]
            logging.debug("[{}] Use instance: {}".format(gui_alias, id(self.gui_coam)))
            self._close_startup_view_if_exists(bts_id, du_id)
            try:
                result = web_fun(**passed_args)
                return result
            except Exception as ex:
                reconnect = True
                logging.warning("Cannot call method {}. Caught exception: {}".format(web_fun.__name__, repr(ex)))
                logging.warning("Try to login again")
                self.gui_coam.save_screenshot(filename='exception', sbts=gui_alias)

        if reconnect:
            try:
                self._login_gui_after_screen_lock(bts_id, du_id)
            except (TimeoutException, ElementClickInterceptedException, MaxRetryError):
                logging.debug("Login failed, Close browser and login again")
                self._teardown_browser(bts_id, du_id)
                self.login_gui(bts_id=bts_id, du_id=du_id)

        return web_fun(**passed_args)

    return wrapper


def convert_id_to_int(fun):
    @wraps(fun)
    def wrapper(*args, **kwargs):
        passed_args = getcallargs(fun, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])
        passed_args['du_id'] = int(passed_args['du_id'])

        result = fun(**passed_args)
        return result

    return wrapper


all_generic_bts_instances = {}
selenium_browser_instances = {}


class GenericBts(object):
    """Generic keywords for eNB and gNB"""

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    admin = cadmin()
    coam_used_ip = {}

    gui_coam = None

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericBts class.

        :param bts_type: GNB|ENB
        """
        self.ROBOT_LIBRARY_LISTENER = self

        self.bts_type = bts_type

        self.rest_alias = device_aliases.rest_bts_du.format(bts_type, '{}', '{}')
        self.fdsw_alias = device_aliases.fdsw_bts_du.format(bts_type, '{}', '{}')
        self.gui_alias = device_aliases.gui_bts_du.format(bts_type, '{}', '{}')
        self.ssh_alias = device_aliases.ssh_bts_du.format(bts_type, '{}', '{}')
        self.ssh_cu_alias = device_aliases.ssh_cu_unit.format(bts_type, '{}', '{}', '{}')
        self.ssh_cu_lmp_alias = device_aliases.ssh_cu_unit_lmp.format(bts_type, '{}', '{}', '{}')
        self.ssh_cap_unit_alias = device_aliases.ssh_cap_unit.format(bts_type, '{}', '{}', '{}', '{}')
        self.syslog_alias = device_aliases.syslog_bts_du.format(bts_type, '{}', '{}')
        self.ssh_ru_alias = device_aliases.ssh_bts_du_ru.format(bts_type, '{}', '{}', '{}')

        self.ws_du_alias = device_aliases.ws_du.format(bts_type, '{}', '{}')

        self.patterns = GnbDistNamePatterns if bts_type == 'GNB' else EnbDistNamePatterns
        self.ws_ru_pattern = "RU{}_WS$"

        all_generic_bts_instances[id(self)] = type(self).__name__

    def __del__(self):
        if id(self) in all_generic_bts_instances:
            logging.debug("Destroy instance of {}. ID: {}".format(type(self).__name__, id(self)))
            del all_generic_bts_instances[id(self)]
            if not all_generic_bts_instances:
                logging.debug("It's last GenericBts instance - teardown connections")
                self._close()

    def _close(self):
        """
        Called when robot test execution ends
        """
        self.teardown_all_browsers()
        self._teardown_all_aliases()

    def connect(self, bts_id=0, du_id=0, reconnect_attempts=3, via_proxy=None, interface='mplane', force=False,
                timeout=60, log_dir=None, use_lmp_if_mplane_unreachable=True):
        """
        Connect to BTS

        .. note::
            Please remember that by default you should connect to BTS via m-Plane address.
            Only if BTS is not commissioned (or you lost connection via m-Plane) you can use LMP option.

        :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param reconnect_attempts:  max reconnect attempts
        :param via_proxy:  If True: connect via PC and LMP address - You need to have configured
                                    test_pcs or proxy for lmp_connection
                           IF False: connect directly from UTE VM.
        :param interface:  connect via 'mplane' or 'lmp'
        :param force:      True/False - If True - first disconnect if already connected.
        :param timeout:    Time to wait for Admin API setup
        :param log_dir:    Directory for Admin API logs
        :param use_lmp_if_mplane_unreachable: If True: if m-Plane is unreachable, try to connect via LMP
        """

        if via_proxy is not None:
            logging.warning("'via_proxy' option is deprecated - Please use 'interface' parameter instead.")

        rest_alias = self.rest_alias.format(bts_id, du_id)
        if force:
            self.disconnect(bts_id=bts_id, du_id=du_id)

        if rest_alias in [item[0] for item in self.admin.store.all]:
            logging.debug("[{}] Already connected via [{}]- skipping setup connection".
                          format(rest_alias, self.coam_used_ip.get(rest_alias)))
            return

        attempt = 0
        admin_exception = None
        current_interface = interface

        while attempt <= reconnect_attempts:
            attempt += 1
            logging.debug("[{}] Connect to ADMIN via {} - attempt: {}".format(rest_alias, current_interface, attempt))
            try:
                self._connect(bts_id=bts_id, du_id=du_id, interface=current_interface, timeout=timeout,
                              log_dir=log_dir)
                self.coam_used_ip[rest_alias] = self._get_proper_ip_address(current_interface,
                                                                            bts_id=bts_id, du_id=du_id)
                if not self._check_bts_version(bts_id=bts_id, du_id=du_id):
                    self.disconnect(bts_id=0, du_id=0)
                    continue
                break
            except (AdminApiConnectionClosedException, AdminApiTerminatedException) as e:
                admin_exception = e
                logging.debug(f"[{rest_alias}][{type(e)}] cannot connect to bts")
                self.disconnect(bts_id, du_id)
                is_lmp_pingable = self.lmp_is_pingable_from_ws(bts_id=bts_id, du_id=du_id)
                if current_interface == 'mplane':
                    is_mplane_pingable = self.mplane_is_pingable_from_ws(bts_id=bts_id, du_id=du_id)
                    msg = "[{}] Cannot connect via m-Plane".format(rest_alias)
                    if is_mplane_pingable:
                        msg += " - m-Plane address is pingable - Please check logs why it was not possible."
                    else:
                        msg += " because of m-Plane address is not pingable"
                        if not is_lmp_pingable:
                            msg += " and LMP address is not pingable too - most probbably BTS is not ready after reboot/reset."
                        else:
                            msg += " but LMP address is pingable. Potential Truck Roll or BTS is not commissioned"

                    if use_lmp_if_mplane_unreachable:
                        msg += "\nTry to connect via LMP in next attempt"
                        logging.warning(msg)
                        current_interface = 'lmp'
                    else:
                        logging.debug(msg)
                else:
                    if is_lmp_pingable:
                        logging.debug("[{}] LMP address is pingable".format(rest_alias))
                        if attempt == reconnect_attempts:
                            logging.debug("Dumping current disk space usage on VM")
                            dump_current_disk_space_usage_on_ute_vm()
                    else:
                        logging.debug("[{}] LMP address is not pingable - most probably "
                                      "BTS is not ready after reboot/reset".format(rest_alias))
        else:
            if admin_exception:
                raise admin_exception

    def check_if_bts_connection_working_and_reset_if_needed(self, bts_id=0, du_id=0):
        logging.debug("[{}] Check if BTS connection is working".format(self.rest_alias.format(bts_id, du_id)))
        try:
            status = self._check_bts_version(bts_id=bts_id, du_id=du_id)
            if not status:
                rest_alias = self.rest_alias.format(bts_id, du_id)
                used_ip = self.coam_used_ip.get(rest_alias)
                used_interface = 'lmp' if used_ip and used_ip.startswith('192.168') else 'mplane'
                self.connect(bts_id=bts_id, du_id=du_id, interface=used_interface, force=True,
                             timeout=120, reconnect_attempts=5)
            else:
                logging.debug("[{}] Connection is working - no need to reconnect".format(
                    self.rest_alias.format(bts_id, du_id)))
        except AliasLookupError:
            logging.debug("[{}] Not connected - try to connect".format(self.rest_alias.format(bts_id, du_id)))
            self.connect(bts_id=bts_id, du_id=du_id)

    def _get_admin_api_log_dir(self, bts_id=0, du_id=0, base_dir=None):
        if base_dir is None:
            base_dir = get_log_path()
        return os.path.join(base_dir, 'admin_api_logs', self.rest_alias.format(bts_id, du_id))

    def _connect(self, bts_id=0, du_id=0, interface='mplane', timeout=60, log_dir=None):
        """
        Connects to bts.
        :param bts_id: bts id
        :param du_id: du id
        :param interface:  connect via 'mplane' or 'lmp'
        :param timeout: Time to wait for Admin API setup
        :param log_dir: Directory for Admin API logs
        :return: None
        """
        rest_alias_name = self.rest_alias.format(bts_id, du_id)
        if log_dir is None:
            log_dir = self._get_admin_api_log_dir(bts_id=bts_id, du_id=du_id)
        os.makedirs(log_dir, exist_ok=True)
        credentials = tl_config.get_web_credentials_for_du(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        common_params = {
            'username': credentials['username'],
            'password': credentials['password'],
            'name': rest_alias_name,
            'admin_api_log_dir': log_dir,
            'update_interval': 500,
            'timeout': timeout
        }
        if interface.lower() == 'mplane':
            if self._check_if_lmp_address(address=credentials['ip']):
                logging.warning("Connection to WebEM should be done via m-Plane address."
                                " Please put m-Plane address in 'oam_http_connection_details'"
                                " Current defined address is LMP: {}".format(credentials['ip']))
            logging.debug("[{}] Use direct connection via m-Plane {}".format(
                self.rest_alias.format(bts_id, du_id), credentials['ip']))
            self.admin.connect_to(bts_host=credentials['ip'], **common_params)
        elif interface.lower() == 'lmp':
            lmp_address = self._get_lmp_ip_address(bts_id=bts_id, du_id=du_id)
            if self.check_if_local_pc_is_the_same_machine_as_bts_ws(bts_id=bts_id, du_id=du_id):
                logging.debug("[{}] Use direct connection via LMP {}".format(
                    self.rest_alias.format(bts_id, du_id), lmp_address))
                self.admin.connect_to(bts_host=lmp_address, **common_params)
            else:
                proxy_credentials = tl_config.get_bts_ws_credentials(bts_id=bts_id, du_id=du_id,
                                                                     bts_type=self.bts_type)
                logging.debug("[{}] Use connection via LMP and Workstation [{}] proxy".
                              format(rest_alias_name, self.ws_du_alias.format(bts_id, du_id)))
                self.admin.setup_admin(bts_host=lmp_address,
                                       remote_host=proxy_credentials['host'],
                                       remote_host_username=proxy_credentials['user'],
                                       remote_host_password=proxy_credentials['password'],
                                       **common_params
                                       )

    def disconnect(self, bts_id=0, du_id=0):
        """
        Disconnect from BTS

        :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        name = self.rest_alias.format(bts_id, du_id)
        try:
            self.admin.teardown(connection=name)
        except AliasLookupError:
            logging.debug("[{}] Already disconnected".format(name))

    def get_admin_connection_alias(self, bts_id=None, du_id=None, connection=None):
        """
        Get Admin API connection alias

        :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param connection:  If given, return this connection alias instead of constructing a new one based
                            on bts_id and du_id
        :return: Admin API connection alias
        """
        if (bts_id is None or du_id is None) and connection is None:
            raise ValueError("Please specify both bts_id and du_id, or provide a connection")

        connection_alias = connection or self.rest_alias.format(bts_id, du_id)
        return connection_alias

    def login_gui(self, bts_id=0, du_id=0, log_dir=None):
        """
        Login to BTS via GUI

        :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param log_dir:     Directory for GUI logs
        :return: None
        """

        self.gui_coam = selenium_coam_sbts()
        logging.debug("[{}] Created new instance: {}".format(self.gui_alias.format(bts_id, du_id), id(self.gui_coam)))

        if selenium_browser_instances:
            self.gui_coam._display = list(selenium_browser_instances.values())[0]._display
        else:
            logging.debug("Enable Virtual Display")
            self.gui_coam.enable_virtual_display()

        selenium_browser_instances[self.gui_alias.format(bts_id, du_id)] = self.gui_coam

        try:
            self._login_gui(bts_id, du_id, log_dir=log_dir)
        except TimeoutException:
            logging.warning("Login failed")

    def _close_startup_view_if_exists(self, bts_id=0, du_id=0):
        if self.gui_coam.start_up_view_window_exists(sbts=self.gui_alias.format(bts_id, du_id)):
            self.gui_coam.close_start_up_view_window(sbts=self.gui_alias.format(bts_id, du_id))

    def _login_gui(self, bts_id=0, du_id=0, timeout=120, log_dir=None):
        gui_alias = self.gui_alias.format(bts_id, du_id)
        logging.debug("[{}] New GUI connection".format(gui_alias))
        credentials = tl_config.get_web_credentials_for_du(bts_id, du_id, self.bts_type)
        if log_dir is None:
            log_dir = os.path.join(get_log_path(), 'selenium_logs', gui_alias)
        download_folder = os.path.join(log_dir, "download")
        if not os.path.exists(download_folder):
            os.makedirs(download_folder)
        try:
            self.gui_coam.login(url='https://{}/'.format(credentials['ip']),
                                username=credentials['username'],
                                password=credentials['password'],
                                screenshot_dir=os.path.join(log_dir, 'screenshot'),
                                download_dir=download_folder,
                                version=self._get_proper_coam_selenium_version(bts_id, du_id),
                                alias=gui_alias,
                                timeout=timeout)
        except TimeoutException:
            logging.warning("Login failed, Try to use method login_after_screen_lock")
            self._login_gui_after_screen_lock(bts_id, du_id)

    def _login_gui_after_screen_lock(self, bts_id=0, du_id=0):
        credentials = tl_config.get_web_credentials_for_du(bts_id, du_id, self.bts_type)
        self.gui_coam.login_after_screen_lock(passwd=credentials['password'], timeout=60,
                                              sbts=self.gui_alias.format(bts_id, du_id))

    def logout_gui(self, bts_id=0, du_id=0):
        """
        Logout from BTS via GUI

        :return: None
        """
        for x in range(3):
            try:
                self.gui_coam.logout(sbts=self.gui_alias.format(bts_id, du_id))
                break
            except (ElementClickInterceptedException, MaxRetryError, TimeoutException):
                time.sleep(5)
        self._teardown_browser(bts_id, du_id)

    def _teardown_browser(self, bts_id=0, du_id=0):
        gui_alias = self.gui_alias.format(bts_id, du_id)
        logging.debug("[{}] Close Browser".format(gui_alias))
        self.gui_coam.close_browser(sbts=gui_alias)
        del selenium_browser_instances[gui_alias]

    def teardown_all_browsers(self):
        for gui_alias, gui_coam in selenium_browser_instances.copy().items():
            if gui_alias in selenium_browser_instances:
                logging.debug("[{}] Close Browser".format(gui_alias))
                gui_coam.close_browser(sbts=gui_alias)
                del selenium_browser_instances[gui_alias]

    def get_bts_instance_id(self, bts_id=0, du_id=0):
        """
        Get BTS Instance id from config file.

        :param bts_id:                  enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: global BTS ID - MRBTS
        """

        return tl_config.get_bts_instance_id(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)

    def get_global_bts_id(self, bts_id=0, du_id=0):
        """
        Get global BTS id from config file.

        :param bts_id:                  enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: global BTS ID, nrbts_id for GNB or lnbts_id for ENB
        """

        return tl_config.get_global_bts_id(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)

    def get_bts_config(self, bts_id=0):
        """
        Get Bts instance form config file
        :param bts_id:  enb_id or gnb_id, related to test line configuration, default set to 0
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: instance of bts
        """
        return tl_config._get_bts_object(bts_id=bts_id, bts_type=self.bts_type)

    def _get_object_parameters_dict(self, dist_name, bts_id, du_id):
        """
        Create python dictionary from current scf content.

        :param dist_name:               full class path to target object e.g "MRBTS-1/NRBTS-1/NRCELL-1"
        :type dist_name:                full class path
        :param bts_id:                  gNB or eNB ID as int
        :param du_id:                   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:                        parameters and values in form of dictionary
        :rtype:                         dict
        """
        bts_configuration = self.admin.get_scf(export_type="configurationAndRuntimeObjects",
                                               connection=self.rest_alias.format(bts_id, du_id))
        ret = str(bts_configuration).partition('distName="{}"'.format(dist_name))[2].partition('</managedObject>')[0]
        re_parameter_and_value = r'\s+<p\s\w+=.(?P<KEY>\w+).>(?P<VALUE>.*)</p>'
        ret_dict = {}
        for line in ret.splitlines():
            determinate_parameter = re.search(re_parameter_and_value, line)
            if determinate_parameter:
                ret_dict[determinate_parameter.group('KEY')] = determinate_parameter.group('VALUE')
        return ret_dict

    def _verify_configuration_parameters_values(self, param_dict, bts_id=0, du_id=0):
        """
        Verify that given parameters have given values.
        :param param_dict: dictionary where the main key is a distNames of the managedObject
        where given parameters are located and the value is dictionary with parameters and their
        expected values,
        e.g. {  distName1: {
                  param1: expected_value1,
                  param2: expected_value2
                },
                distName2: {
                  param1: expected_value1,
                  param2: expected_value2
                }
            }
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id:  DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        param_dict_with_proper_distnames = {}
        for dist_name in param_dict.keys():
            proper_dist_name = self.adjust_dist_name(dist_name=dist_name, bts_id=bts_id, du_id=du_id)
            param_dict_with_proper_distnames[proper_dist_name] = param_dict[dist_name]

        for dist_name in param_dict_with_proper_distnames.keys():
            for param_name in param_dict_with_proper_distnames[dist_name]:
                self._verify_parameter_value(parameter=param_name,
                                             expected_value=param_dict_with_proper_distnames[dist_name][param_name],
                                             dist_name=dist_name,
                                             bts_id=bts_id,
                                             du_id=du_id)
        logging.info("All parameters have correct values")

    def _verify_parameter_value(self, parameter, expected_value, dist_name, bts_id, du_id):
        """
        Verify if current value of parameter is consistent with expected value.

        :param parameter:               parameter name
        :type parameter:                str
        :param expected_value:          expected value of parameter
        :type expected_value:           str
        :param dist_name:               full class path to target object e.g "MRBTS-1/NRBTS-1/NRCELL-1"
        :type dist_name:                full class path
        :param bts_id:                  enb_id or gnb_id, related to test line configuration, default set to 0
        :type bts_id:                   int or str
        :param du_id:                   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type bts_id:                   int or str
        :return
        """
        try:
            value = self._get_object_parameters_dict(dist_name=dist_name, bts_id=bts_id, du_id=du_id)[parameter]
        except KeyError:
            raise DataNotAvailable(
                "'{}' doesn't exist in bts configuration (check if keyword arguments are correct)".format(parameter))
        if not re.match(expected_value, value, re.I):
            raise IncorrectParameterValue("'{}' should be '{}' but is '{}'".format(parameter, expected_value, value))
        else:
            logging.info("Parameter '{}' is '{}'".format(parameter, expected_value))

    def adjust_dist_name(self, dist_name, bts_id, du_id=0):
        """
        Adjust mrbts_id and global bts id (nrbts_id or lnbts_id) in given distName.

        :param dist_name:               distName in format e.g. MRBTS-{}/NRBTS-{}/NRCELL-1
        :type dist_name:                str
        :param bts_id:                  enb_id or gnb_id, related to test line configuration, default set to 0
        :type bts_id:                   int or str
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type du_id:                    int or str
        :return: distName with proper values
        """
        mrbts_id = self.get_bts_instance_id(bts_id=bts_id, du_id=du_id)
        global_bts_id = self.get_global_bts_id(bts_id=bts_id, du_id=du_id)
        return dist_name.format(mrbts_id, global_bts_id)

    @login_logout
    def is_sbts_software(self, bts_id=0, du_id=0):
        """
        Verify SBTS software.
        :param bts_id:          BTS id - related to Test Line configuration. Default: 0
        :type bts_id:           int
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:                True/False
        """
        release = self.admin.get_sw_release_name(connection=self.rest_alias.format(bts_id, du_id))
        is_sbts = "SBTS" in release
        return is_sbts

    @staticmethod
    def __get_supported_selenium_releases():
        from taf.selenium.sbts.provider import SupportedSbts
        supported_releases = dir(SupportedSbts)
        supported_releases = [attr_name for attr_name in supported_releases if not attr_name.startswith('_')]
        supported_releases.sort()
        return supported_releases

    @login_logout
    def _get_proper_coam_selenium_version(self, bts_id=0, du_id=0):
        selected_version = None
        supported_versions = self.__get_supported_selenium_releases()
        release = self.admin.get_sw_release_name(connection=self.rest_alias.format(bts_id, du_id))
        logging.debug("[{}] Release version: {}".format(self.rest_alias.format(bts_id, du_id), release))

        if release:
            only_release_number = None
            # 5G21A, SBTS21B, 5G22R1
            match = re.search(r'(\d+(?:([A-C])|(R\d+)))', release)
            if match:
                only_release_number = match.group(0)
                logging.debug("[{}] Release number: {}".format(self.rest_alias.format(bts_id, du_id),
                                                               only_release_number))
            if only_release_number:
                for version in supported_versions:
                    if only_release_number.lower() in version.lower():
                        selected_version = version
                        break

        if selected_version is None:
            selected_version = supported_versions[-1]
        logging.debug("Selected selenium version: {}".format(selected_version))
        return selected_version

    def mplane_is_pingable_from_ws(self, bts_id=0, du_id=0):
        mplane_address = tl_config.get_oam_ip_address(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        return self._address_is_pingable_from_ws(address=mplane_address, bts_id=bts_id, du_id=du_id)

    def lmp_is_pingable_from_ws(self, bts_id=0, du_id=0):
        lmp_address = self._get_lmp_ip_address(bts_id=bts_id, du_id=du_id)
        return self._address_is_pingable_from_ws(address=lmp_address, bts_id=bts_id, du_id=du_id)

    def _get_proper_ip_address(self, interface, bts_id, du_id):
        if interface == 'lmp':
            return self._get_lmp_ip_address(bts_id=bts_id, du_id=du_id)
        else:
            return tl_config.get_web_credentials_for_du(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)['ip']

    def _get_lmp_ip_address(self, bts_id=0, du_id=0):
        lmp_credentials = tl_config.get_du_lmp_credentials(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        lmp_address = lmp_credentials['host'] if lmp_credentials['host'] else '192.168.255.129'
        return lmp_address

    @load_moler_configuration_from_tl()
    def _address_is_pingable_from_ws(self, address, bts_id=0, du_id=0):
        ws_device_name = self.ws_du_alias.format(bts_id, du_id)
        ws_device = DeviceFactory.get_device(name=ws_device_name)
        ws_device.goto_state(state='UNIX_REMOTE')
        ping_cmd = ws_device.get_cmd(cmd_name="ping", cmd_params={'destination': address, 'options': '-c 7'})
        logging.debug("Ping BTS ({}) from {}".format(address, ws_device_name))
        results = ping_cmd()

        logging.debug("Transmitted: {}".format(results['packets_transmitted']))
        logging.debug("Received: {}".format(results['packets_received']))
        logging.debug("Packed loss: {}%".format(results['packet_loss']))

        return False if results['packet_loss'] == 100 else True

    @staticmethod
    def _check_if_lmp_address(address):
        if '192.168' in address:
            return True
        return False

    @load_moler_configuration_from_tl()
    def check_if_local_pc_is_the_same_machine_as_bts_ws(self, bts_id, du_id):
        ws_du_device = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))
        ws_du_device.goto_state(state='UNIX_REMOTE')
        local_pc_device = DeviceFactory.get_device(name='UnixLocal')
        bts_ws_hostname = ws_du_device.get_cmd(cmd_name='hostname')()['hostname']
        local_pc_hostanme = local_pc_device.get_cmd(cmd_name='hostname')()['hostname']
        if local_pc_hostanme.lower() == bts_ws_hostname.lower():
            return True
        return False

    def _check_bts_version(self, bts_id, du_id):
        alias_name = self.rest_alias.format(bts_id, du_id)
        try:
            sw_ver = self.admin.get_software_info(timeout=60, connection=alias_name)
            logging.debug("[{}] Current BTS version: {}".format(alias_name, sw_ver['Active SW version']))
            return True
        except AdminApiProcedureFailureException as e:
            if 'ErrorCode: 6' in repr(e):
                logging.warning(repr(e))
                logging.warning("Caught 'ErrorCode: 6' - restart connection")
                return False
            elif 'ErrorCode: 7' in repr(e):
                if self._try_to_get_sw_version(alias_name):
                    return True
            else:
                raise e
        except AdminApiNoResponseException as e:
            logging.warning(repr(e))
            logging.warning("restart connection")
            return False

    def _try_to_get_sw_version(self, alias_name, timeout=160, interval=30, get_sw_version_timeout=60):
        logging.debug("[{}] BTS is not commissioned. Get version from BtsInfo".format(alias_name))
        start_time = time.time()
        while time.time() < start_time + timeout:
            try:
                sw_ver = self.admin.get_sw_version(timeout=get_sw_version_timeout, connection=alias_name)
                logging.debug("[{}] Current BTS version: {}".format(alias_name, sw_ver))
                return sw_ver
            except DataNotAvailable as dna:
                logging.debug("Cannot get SW version: {}".format(dna))
                logging.debug("Try to get once again after {} sec".format(interval))
                time.sleep(interval)

    @staticmethod
    def _unify_statuses(statuses, required_keys=None):
        """
        Unify keys and status values to CNI-61110 changes.
        :param statuses: dict of statuses
        :param required_keys: list of required keys
        :return:
        """
        logging.warning("_unify_statuses method is deprecated - please use 'unify_statuses' from "
                        "'taf.rfrl.bts.helpers.compare_statuses'")
        return unify_statuses(statuses, required_keys)

    def _teardown_all_aliases(self):
        """
        Teardown all admin connections created by taf.rfrl.bts library
        """
        _re_alias = re.compile(r'REST_(E|G)NB\d+_DU\d+')
        for connection_name, connection in list(self.admin.store.all):
            if _re_alias.search(connection_name):
                logging.debug("[{}] Closing connection".format(connection_name))
                self.admin.teardown(connection)

    @login_logout
    def is_serial_console_connected(self, bts_id=0, du_id=0, connection=None):
        """
        Check if the serial console is connected to BTS.

        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param connection: (optional) Connection alias. If None, it will be built automatically from bts_id and du_id
        :return: True if the serial console is activated, False otherwise.
        """
        all_active_alarms = self.admin.get_active_alarms(
            connection=self.get_admin_connection_alias(bts_id, du_id, connection))
        for alarm_info in all_active_alarms:
            if int(alarm_info['faultId']) == 4334 and alarm_info['faultName'] == 'Serial console activated':
                return True
        return False
